}
if (write?.ok !== true || !Number.isInteger(Number(write?.FRR_id)) || Number(write.FRR_id) <= 0) return [{ json: { ...write, ok: false, phase: 'write', status: write?.status ?? 'write_not_confirmed', retry_safe: false } }];

